function update_primary_image_view(frm) {
    let source = frm.doc.selected_image_source;
    let path = "";

    // Map your dropdown item options cleanly to the target data points
    if (source === "Left Front Top") {
        path = frm.doc.left_front_top;
    } else if (source === "Left Front Down") {
        path = frm.doc.left_front_down;
    } else if (source === "Left Top") {
        path = frm.doc.left_top;
    } else if (source === "Left Down") {
        path = frm.doc.left_down;
    } else if (source === "Left Back Top") {
        path = frm.doc.left_back_top;
    } else if (source === "Left Back Down") {
        path = frm.doc.left_bac_down;
    } else if (source === "Right Top") {
        path = frm.doc.right_top;
    } else if (source === "Right Down") {
        path = frm.doc.right_down;
    } else if (source === "Right Back Top") {
        path = frm.doc.right_back_top;
    } else if (source === "Right Back Down") {
        path = frm.doc.right_back_down;
    } else if (source === "Front Left") {
        path = frm.doc.front_left;
    } else if (source === "Front Right") {
        path = frm.doc.front_right;
    } else if (source === "Back Left") {
        path = frm.doc.back_left;
    } else if (source === "Back Right") {
        path = frm.doc.back_right;
    } else if (source === "Wheels front Left") {
        path = frm.doc.wheels_front_left;
    } else if (source === "Wheels front Right") {
        path = frm.doc.wheels_front_right;
    } else if (source === "Wheels Back Right") {
        path = frm.doc.wheels_back_right;
    } else if (source === "Wheels Back Left") {
        path = frm.doc.wheels_back_left;
    } else if (source === "Extra1") {
        path = frm.doc.extra1;
    } else if (source === "Extar2") {
        path = frm.doc.extra2;
    } else if (source === "Extar3") {
        path = frm.doc.extra3;
    } else if (source === "Extra4") {
        path = frm.doc.extra4;
    }

    // Get a clean reference link to the targeted field HTML wrapper element
    let target_wrapper = frm.fields_dict['dynamic_preview_image'].wrapper;

    if (path) {
        // Clear old preloads to prevent duplicates
        let existing_preload = document.getElementById("dynamic-img-preload");
        if (existing_preload) existing_preload.remove();

        // Create the preloader tag with explicit types
        let preload_link = document.createElement("link");
        preload_link.id = "dynamic-img-preload";
        preload_link.rel = "preload";
        preload_link.as = "image";
        preload_link.href = path;
        preload_link.setAttribute("fetchpriority", "high");
        document.head.appendChild(preload_link);

        // Force a visibility switch on the wrapper layout wrapper
        frm.toggle_display('dynamic_preview_image', true);

        // Inject a raw semantic layout block directly to guarantee a visible render
        $(target_wrapper).html(`
            <div style="padding: 1px 0;">
                <label class="control-label" style="margin-bottom: 5px;">Selected Image Preview</label>
                <div style="background-color: #f8f9fa; border: 1px solid #d1d8dd; border-radius: 1px; padding: 1px; max-width: 100%; text-align: center;">
                    <img src="${path}" alt="Inspection Asset" style="max-height: 400px; max-width: 100%; object-fit: contain; border-radius: 2px;" />
                </div>
            </div>
        `);
    } else {
        // Cleanly wipe the raw layout area and hide the block from the form frame
        $(target_wrapper).html("");
        frm.toggle_display('dynamic_preview_image', false);

        let existing_preload = document.getElementById("dynamic-img-preload");
        if (existing_preload) existing_preload.remove();
    }
}

frappe.ui.form.on('Inspection_M', {
    refresh(frm) {
        // Toggle visibility of the target section break
        if (!frm.is_new()) {
            frm.set_df_property('section_break_frdd', 'hidden', 0);
        } else {
            frm.set_df_property('section_break_frdd', 'hidden', 1);
        }

        // Handle 'booked_in_signature' state based on actual data existence
        if (frm.doc.booked_in_signature) {
            lock_signature_pad(frm, 'booked_in_signature');
            remove_signature_save_button(frm, 'booked_in_signature');
        } else {
            unlock_signature_pad(frm, 'booked_in_signature');
            render_signature_save_button(frm, 'booked_in_signature');
        }

        // Handle 'driver_signature' state based on actual data existence
        if (frm.doc.driver_signature) {
            lock_signature_pad(frm, 'driver_signature');
            remove_signature_save_button(frm, 'driver_signature');
        } else {
            unlock_signature_pad(frm, 'driver_signature');
            render_signature_save_button(frm, 'driver_signature');
        }
    },

    after_save: function(frm) {
        // Evaluate inputs immediately upon successful save
        if (frm.doc.booked_in_signature) {
            lock_signature_pad(frm, 'booked_in_signature');
            remove_signature_save_button(frm, 'booked_in_signature');
        }
        if (frm.doc.driver_signature) {
            lock_signature_pad(frm, 'driver_signature');
            remove_signature_save_button(frm, 'driver_signature');
        }

        // Cleanly handle accordion section snapping routines
        let attempts = 0;
        let forceLayout = setInterval(() => {
            frm.set_df_property('section_break_frdd', 'hidden', 0);

            frm.layout.fields_list.forEach(field => {
                if (field.df.fieldtype === 'Section Break') {
                    if (field.df.fieldname === 'section_break_frdd') {
                        field.collapsed = false;
                        field.collapse(false);

                        if (field.$wrapper) {
                            field.$wrapper.find('.section-body').removeClass('collapse').addClass('show');
                            field.$wrapper.find('.section-head').removeClass('collapsed').attr('aria-expanded', 'true');
                        }
                    } else {
                        field.collapsed = true;
                        field.collapse(true);
                    }
                }
            });

            attempts++;
            if (attempts > 5) {
                clearInterval(forceLayout);

                let targetSection = frm.get_field('section_break_frdd');
                if (targetSection) {
                    frappe.utils.scroll_to(targetSection.$wrapper);
                }
            }
        }, 150);
    }
});

// FREEZES canvas inputs but leaves visual data visible
function lock_signature_pad(frm, fieldname) {
    let field = frm.get_field(fieldname);
    if (field && field.$wrapper) {
        field.$wrapper.find('.signature-btn-clear').hide();
        field.$wrapper.find('.signature-display, canvas').css({
            'pointer-events': 'none',
            'opacity': '0.95'
        });
    }
}

// RESTORES canvas capabilities if the field is blank
function unlock_signature_pad(frm, fieldname) {
    let field = frm.get_field(fieldname);
    if (field && field.$wrapper) {
        field.$wrapper.find('.signature-btn-clear').show();
        field.$wrapper.find('.signature-display, canvas').css({
            'pointer-events': 'auto',
            'opacity': '1.0'
        });
    }
}

// Generates custom action buttons dynamically
function render_signature_save_button(frm, fieldname) {
    let field = frm.get_field(fieldname);
    if (field && field.$wrapper) {
        field.$wrapper.find('.custom-sig-save-btn').remove();

        let btn_html = `
            <div style="margin-top: 10px;" class="custom-sig-save-btn">
                <button class="btn btn-xs btn-primary btn-custom-save">
                    <i class="fa fa-floppy-o" style="margin-right: 5px;"></i> Save Document & Signature
                </button>
            </div>
        `;

        field.$wrapper.append(btn_html);

        field.$wrapper.find('.btn-custom-save').on('click', function() {
            if (frm.is_dirty()) {
                frappe.show_alert({message: __('Saving changes...'), indicator: 'blue'});
                frm.save();
            } else {
                frappe.show_alert({message: __('No changes detected to save.'), indicator: 'orange'});
            }
        });
    }
}

// Utility function to cleanly drop buttons out of layout context
function remove_signature_save_button(frm, fieldname) {
    let field = frm.get_field(fieldname);
    if (field && field.$wrapper) {
        field.$wrapper.find('.custom-sig-save-btn').remove();
    }
}

frappe.ui.form.on('Inspection_M', {
    refresh(frm) {
        if (!frm.is_new()) {
            frm.set_df_property('section_break_frdd', 'hidden', 0);
        } else {
            frm.set_df_property('section_break_frdd', 'hidden', 1);
        }
    },
    after_save: function(frm) {
        // Use an interval to repeatedly force the state until the core reload settles
        let attempts = 0;
        let forceLayout = setInterval(() => {
            frm.set_df_property('section_break_frdd', 'hidden', 0);

            frm.layout.fields_list.forEach(field => {
                if (field.df.fieldtype === 'Section Break') {
                    if (field.df.fieldname === 'section_break_frdd') {
                        // 1. Force state in the field object
                        field.collapsed = false;
                        field.collapse(false);

                        // 2. Remove the Framework's Bootstrap collapsed classes manually
                        if (field.$wrapper) {
                            field.$wrapper.find('.section-body').removeClass('collapse').addClass('show');
                            field.$wrapper.find('.section-head').removeClass('collapsed').attr('aria-expanded', 'true');
                        }
                    } else {
                        field.collapsed = true;
                        field.collapse(true);
                    }
                }
            });

            attempts++;
            if (attempts > 5) {
                clearInterval(forceLayout);

                // 3. Final smooth scroll once the layout settles
                let targetSection = frm.get_field('section_break_frdd');
                if (targetSection) {
                    frappe.utils.scroll_to(targetSection.$wrapper);
                }
            }
        }, 150); // Fires every 150ms to fight off the native form re-render
    }
});
